#pragma once

#include "CoreMinimal.h"

class UStaticMesh;
class UMaterialInterface;
class UMaterialInstanceDynamic;
class USoundBase;
class UObject;
class UWorld;

/**
 * Central access to the (small) set of assets the game uses.
 * Meshes come from /Engine/BasicShapes. Materials and sounds are generated by
 * Tools/GenerateContent.py into /Game/Materials and /Game/Audio. Everything has
 * an engine fallback so the game still runs if generated content is missing.
 *
 * Generated asset contract:
 *   /Game/Materials/M_ArenaSurface  (opaque, lit)  params: vector "Color", vector "Emissive",
 *                                                  scalar "Roughness", scalar "Metallic", scalar "GridScale"
 *   /Game/Materials/M_ArenaGlow     (unlit, additive translucent) params: vector "Color",
 *                                                  scalar "Intensity", scalar "Opacity"
 *   /Game/Audio/<Name>              USoundWave assets, see ArenaAssets::SoundNames in ArenaAssets.cpp
 */
namespace ArenaAssets
{
	UStaticMesh* Cube();      // 100x100x100 cm, pivot at centre
	UStaticMesh* Sphere();    // 100 cm diameter
	UStaticMesh* Cylinder();  // 100 cm diameter, 100 cm tall, pivot at centre, along Z
	UStaticMesh* Cone();      // 100 cm diameter, 100 cm tall, tip at +Z

	UMaterialInterface* SurfaceMaterial();
	UMaterialInterface* GlowMaterial();

	/** Dynamic instance of the lit surface material. */
	UMaterialInstanceDynamic* MakeSurface(UObject* Outer, const FLinearColor& Color, float Roughness = 0.6f,
		float Metallic = 0.f, const FLinearColor& Emissive = FLinearColor::Black, float GridScale = 1.f);

	/** Dynamic instance of the glow material (beams, projectiles, pickups). */
	UMaterialInstanceDynamic* MakeGlow(UObject* Outer, const FLinearColor& Color, float Intensity = 8.f, float Opacity = 1.f);

	/** Sound by short name, e.g. "S_Explosion". Returns nullptr if missing. Cached. */
	USoundBase* Sound(FName Name);

	/** Play a sound at a location (no-op if missing). */
	void PlaySoundAt(const UObject* WorldContext, FName Name, const FVector& Location, float Volume = 1.f, float Pitch = 1.f);

	/** Play a 2D (UI) sound (no-op if missing). */
	void PlaySound2D(const UObject* WorldContext, FName Name, float Volume = 1.f, float Pitch = 1.f);
}
